[{"order":1,"type":"heading","text":"Gesture Handler Integration and Complex Interactions in React Native"},{"order":2,"type":"paragraph","text":"Building fluid, high-performance gestures in React Native requires moving away from the standard JS-based responder system and leveraging react-native-gesture-handler. This library provides native gesture management, allowing interactions to run smoothly on the UI thread."},{"order":3,"type":"subheading","text":"1. Installation and Configuration"},{"order":4,"type":"paragraph","text":"First, install the library and its peer dependency, react-native-reanimated, which is crucial for running complex animation worklets on the UI thread."},{"order":5,"type":"code","text":"npm install react-native-gesture-handler react-native-reanimated"},{"order":6,"type":"paragraph","text":"Make sure to wrap your root component with GestureHandlerRootView. On Android, this is strictly required to intercept touch events."},{"order":7,"type":"code","text":"import React from 'react';
import { GestureHandlerRootView } from 'react-native-gesture-handler';
import AppNavigator from './src/AppNavigator';

export default function App() {
  return (
    <GestureHandlerRootView style={{ flex: 1 }}>
      <AppNavigator />
    </GestureHandlerRootView>
  );
}"},{"order":8,"type":"subheading","text":"2. Creating a Complex Pan Gesture"},{"order":9,"type":"paragraph","text":"With the new Gesture API introduced in version 2, you can compose and handle pan, pinch, and rotation gestures seamlessly using Reanimated shared values."},{"order":10,"type":"code","text":"import React from 'react';
import { StyleSheet, View } from 'react-native';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import Animated, { useSharedValue, useAnimatedStyle, withSpring } from 'react-native-reanimated';

export default function ComplexGestureScreen() {
  const translationX = useSharedValue(0);
  const translationY = useSharedValue(0);
  const prevTranslationX = useSharedValue(0);
  const prevTranslationY = useSharedValue(0);

  const panGesture = Gesture.Pan()
    .onStart(() => {
      prevTranslationX.value = translationX.value;
      prevTranslationY.value = translationY.value;
    })
    .onUpdate((event) => {
      translationX.value = prevTranslationX.value + event.translationX;
      translationY.value = prevTranslationY.value + event.translationY;
    })
    .onEnd(() => {
      translationX.value = withSpring(0);
      translationY.value = withSpring(0);
    });

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [
      { translateX: translationX.value },
      { translateY: translationY.value },
    ],
  }));

  return (
    <View style={styles.container}>
      <GestureDetector gesture={panGesture}>
        <Animated.View style={[styles.box, animatedStyle]} />
      </GestureDetector>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#f0f0f0',
  },
  box: {
    width: 100,
    height: 100,
    backgroundColor: '#6200ee',
    borderRadius: 20,
  },
});"},{"order":11,"type":"subheading","text":"3. Composing Multiple Gestures"},{"order":12,"type":"paragraph","text":"Complex UI components often require simultaneous gestures, such as pinching to zoom while panning across the screen. You can use Gesture.simultaneous to achieve this."},{"order":13,"type":"code","text":"const scale = useSharedValue(1);
const savedScale = useSharedValue(1);

const pinchGesture = Gesture.Pinch()
  .onUpdate((event) => {
    scale.value = savedScale.value * event.scale;
  })
  .onEnd(() => {
    savedScale.value = scale.value;
  });

const composedGesture = Gesture.simultaneous(panGesture, pinchGesture);"},{"order":14,"type":"subheading","text":"Best Practices"},{"order":15,"type":"bullet_point","text":"Always execute worklets on the UI thread by using 'worklet' directives or Reanimated hooks."},{"order":16,"type":"bullet_point","text":"Avoid calling React state setters inside high-frequency gesture update callbacks to prevent frame drops."},{"order":17,"type":"bullet_point","text":"Use withSpring and withTiming utilities from Reanimated for smooth settling animations once a gesture ends."}]
